// Fox Defence - Tower Defense Game
// Original Processing sketch by Joseph Priatel (Programming 12)
// Web port to p5.js so it can run on GitHub Pages.

// ================ GLOBAL VARIABLES =================
const INTRO = 0;
const PLAY = 1;
const BUILD = 2;
const GAMEOVER = 3;

const PLACING = 0;
const PLACED = 1;
const GUN = 2;
const AOE = 3;
const LASER = 4;

let mode;
let lives = 3;
let cashmoney = 100;
let textsize = 100;
let angle = 0;

// Palette (hex strings)
const white = '#ffffff';
const black = '#000000';
const grassgreen = '#168564';
const rockgreyl = '#324c53';
const rockgreyd = '#2a4346';
const foxredl = '#e84c5f';
const foxredd = '#983b3c';

// Mouse interaction.
// Processing polls mousePressed every frame; a very quick tap can fall
// between two frames, so we latch press/release events from the callbacks.
let mouseWasReleased = false; // true for the one frame after a click finishes
let mouseHeld = false;        // true while the mouse is down (or was pressed this frame)
let isDown = false;
let pressedLatch = false;
let releasedLatch = false;

// Buttons
let start, waveBtn, buildBtn, playBtn;
let buyGunTowerButton, buyAoeTowerButton, buyLaserTowerButton;
let map1Button, map2Button, speed1xButton, speed2xButton;

// Collections of objects
let nodes;
let mobs, towers, bullets;

// Images, Gifs, fonts
let introAnimation, playb, map1, map2, retroica;

// Play / build state
let waveCount = 1;
let mobCount = 0;
let mobSpawn = 0;
let mobx = 0;
let mapNum = 0; // "map" in the Processing version (renamed: p5 has its own map())
let multiplier = 1;

// Build screen state
let buildmodetexthue = 0;
let insfundtexthue = 0;
let angle2 = 0;
let draw100 = 0, draw200 = 0, draw300 = 0;
let k = 0;
let deduct100 = false, deduct200 = false, deduct300 = false;

// ================ HELPERS =================
const _rgbCache = {};
function rgbOf(hex) {
  if (!_rgbCache[hex]) {
    const n = parseInt(hex.slice(1), 16);
    _rgbCache[hex] = [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }
  return _rgbCache[hex];
}
function fillA(hex, a) { const c = rgbOf(hex); fill(c[0], c[1], c[2], a); }
function strokeA(hex, a) { const c = rgbOf(hex); stroke(c[0], c[1], c[2], a); }

// Processing draws text with fill only; p5 also outlines it with the current
// stroke. This keeps the original look.
function drawText(str, x, y) {
  push();
  noStroke();
  text(str, x, y);
  pop();
}

// Processing's endTransform() - nothing in this game uses a global transform,
// so resetting to identity is equivalent.
function endTransform() { resetMatrix(); }

// ===================== PRELOAD / SETUP =========================
function preload() {
  introAnimation = new Gif('fox', 77, 1, 500, 400, 1000, 800);
  playb = loadImage(ASSETS.play);
  map1 = loadImage(ASSETS.map1);
  map2 = loadImage(ASSETS.map2);
  retroica = loadFont(ASSETS.font);
}

function setup() {
  createCanvas(1000, 800);
  frameRate(60);
  rectMode(CENTER);
  imageMode(CENTER);
  textAlign(CENTER, CENTER);
  mode = INTRO;
  mobs = [];
  towers = [];
  bullets = [];
  mobCount = mobs.length;
  makeButtons();
  makeNodes();
  textsize = 100;
}

function makeButtons() {
  // INTRO - Start
  start = new Button('PLAY', 500, 575, 400, 200, '#6bd6b5', '#e9fffa');

  // PLAY - Next Wave, To Build Mode
  waveBtn = new Button(playb, 900, 100, 150, 150, '#7BCAB2', '#94E3CC');
  buildBtn = new Button('', 900, 330, 150, 150, '#7BCAB2', '#94E3CC');
  speed1xButton = new Button('', 900, 505, 150, 150, '#7BCAB2', '#94E3CC');
  speed2xButton = new Button('', 900, 680, 150, 150, '#7BCAB2', '#94E3CC');

  map1Button = new Button(map1, 250, 300, 400, 400, '#7BCAB2', '#94E3CC');
  map2Button = new Button(map2, 750, 300, 400, 400, '#7BCAB2', '#94E3CC');

  // BUILD - To play mode, Buy Laser, Buy Gun, Buy AoE
  playBtn = new Button('', 900, 100, 150, 150, '#7BCAB2', '#94E3CC');
  buyGunTowerButton = new Button('', 900, 330, 150, 150, '#7BCAB2', '#94E3CC');
  buyAoeTowerButton = new Button('', 900, 505, 150, 150, '#7BCAB2', '#94E3CC');
  buyLaserTowerButton = new Button('', 900, 680, 150, 150, '#7BCAB2', '#94E3CC');
}

function makeNodes() {
  nodes = [];
  // Map 1
  nodes[0] = new PathNode(175, 525, 0.70711, 0.70711, 45, 1);
  nodes[1] = new PathNode(300, 650, 1, 0, 0, 1);
  nodes[2] = new PathNode(475, 650, 0, -1, 270, 1);
  nodes[3] = new PathNode(475, 175, -1, 0, 180, 1);
  nodes[4] = new PathNode(300, 175, 0, 1, 90, 1);
  nodes[5] = new PathNode(300, 350, 1, 0, 0, 1);
  nodes[6] = new PathNode(650, 350, 0, 1, 90, 1);
  nodes[7] = new PathNode(650, 525, 1, 0, 0, 1);

  // Map 2
  nodes[8] = new PathNode(175, 250, 0, 1, 90, 2);
  nodes[9] = new PathNode(175, 425, 1, 0, 0, 2);
  nodes[10] = new PathNode(350, 425, 0, 1, 90, 2);
  nodes[11] = new PathNode(350, 600, 1, 0, 0, 2);
  nodes[12] = new PathNode(525, 600, 0.70711, -0.70711, -45, 2);
  nodes[13] = new PathNode(700, 425, 1, 0, 0, 2);
}

// ===================== DRAW ===========================
function draw() {
  click();
  if (mode === INTRO) {
    intro();
  } else if (mode === PLAY) {
    play();
  } else if (mode === BUILD) {
    build();
  } else if (mode === GAMEOVER) {
    gameOver();
  }
}

// ===================== MOUSE ===========================
function mousePressed() {
  isDown = true;
  pressedLatch = true;
}

function mouseReleased() {
  isDown = false;
  releasedLatch = true;
}

// utilities.pde
function click() {
  mouseWasReleased = releasedLatch;
  mouseHeld = isDown || pressedLatch;
  releasedLatch = false;
  pressedLatch = false;
}

// ===================== INTRO / GAMEOVER ===========================
function intro() {
  introAnimation.show();
  introLayout();
}

function introLayout() {
  fill('#5BB197');
  strokeWeight(10);
  textFont(retroica);
  textSize(textsize);
  drawText('FOX DEFENCE', 500, 375);
  start.show();
  textsize = sin(angle) * 20 + 110;
  angle = angle + 0.05;

  if (start.clicked) {
    mode = PLAY;
  }
}

function gameOver() {
  background(255);
  textSize(100);
  fill(230);
  drawText('GAMEOVER', 500, 400);
}

// ===================== PLAY ===========================
function play() {
  drawMaps();
  animateThings();
  drawPlayInterface();
  speedButtons();
  transactions();
  drawLives();
  mapSelect();
}

function drawMaps() {
  if (mapNum === 1) drawMap1();
  if (mapNum === 2) drawMap2();
}

function drawPlayInterface() {
  sidebar();
  drawWaveButton();
  drawBuildButton();
  buildATowerText();
}

function mapSelect() {
  if (mapNum === 0) {
    fill('#324c53');
    stroke('#2a4346');
    strokeWeight(15);
    rect(500, 400, 1000, 800);
    map1Button.show();
    fill(white);
    textSize(125);
    drawText('MAP 1', 250, 600);
    if (map1Button.clicked) {
      mapNum = 1;
    }
    map2Button.show();
    textSize(125);
    fill(white);
    drawText('MAP 2', 750, 600);
    if (map2Button.clicked) {
      mapNum = 2;
    }
  }
}

function animateThings() {
  let i = 0;
  while (i < mobs.length) {
    const myMob = mobs[i];
    myMob.act();
    myMob.show();
    if (myMob.hp <= 0) {
      mobs.splice(i, 1);
      cashmoney = cashmoney + 25;
    } else {
      i++;
    }
  }

  i = 0;
  while (i < bullets.length) {
    const myBullet = bullets[i];
    myBullet.act();
    myBullet.show();
    if (myBullet.hp <= 0) {
      bullets.splice(i, 1);
    } else {
      i++;
    }
  }

  i = 0;
  while (i < towers.length) {
    const myTower = towers[i];
    myTower.act();
    myTower.show();
    i++;
  }
}

function sidebar() {
  strokeWeight(15);
  fill('#324c53');
  stroke('#2a4346');
  rect(900, 400, 185, 785);
  fill(white);
  textSize(20);
  drawText('Next Wave: ' + waveCount, 900, 200);
  drawText('Money: $' + cashmoney, 900, 225);
}

function drawRocks() {
  fill(rockgreyl);
  stroke(rockgreyd);
  strokeWeight(10);
  rect(100, 60, 175, 75, 10, 50, 30, 60);
  rect(125, 115, 75, 65, 50, 15, 40, 20);

  rect(615, 65, 75, 65, 60, 20, 15, 40);
  rect(680, 35, 175, 75, 10, 50, 30, 60);
  rect(650, 75, 75, 65, 60, 20, 15, 40);

  rect(570, 740, 65, 45, 15, 25, 10, 20);
}

function drawMap1() {
  background(grassgreen);
  // Path
  stroke('#6ed8b7');
  strokeWeight(30);
  line(0, 525, 175, 525);
  line(175, 525, 300, 650);
  line(300, 650, 475, 650);
  line(475, 650, 475, 350);
  line(475, 350, 475, 350);
  line(475, 350, 475, 175);
  line(475, 175, 300, 175);
  line(300, 175, 300, 350);
  line(300, 350, 475, 350);
  line(475, 350, 650, 350);
  line(650, 350, 650, 525);
  line(650, 525, 800, 525);
  drawRocks();
}

function drawMap2() {
  background(grassgreen);
  // Path
  stroke('#6ed8b7');
  strokeWeight(30);
  line(-50, 250, 0, 250);

  line(0, 250, 175, 250);
  line(175, 250, 175, 425);
  line(175, 425, 350, 425);
  line(350, 425, 350, 600);
  line(350, 600, 525, 600);
  line(525, 600, 700, 425);
  line(700, 425, 850, 425);
  drawRocks();
}

function spawnMobs(spawnY) {
  if (waveCount < 5) {
    spawnStep(spawnY, 0);
  }
  if (waveCount > 4 && waveCount < 6) {
    spawnStep(spawnY, 1);
  }
  if (waveCount > 5) {
    spawnStep(spawnY, floor(random(0, 3)));
  }
}

function spawnStep(spawnY, type) {
  if (mobSpawn > mobs.length) {
    mobs.push(new Mob(mobx, spawnY, 1, 0, type));
    mobx = mobx - 55;
  } else {
    mobSpawn = 0;
    mobx = 0;
  }
}

function drawWaveButton() {
  waveBtn.show();
  if (waveBtn.clicked && mobs.length === 0 && towers.length > 0) {
    waveCount = waveCount + 1;
    mobCount = mobCount + 1;
    mobSpawn = mobCount;
    let i = 0;
    while (i < towers.length) {
      towers[i].cooldown = floor(random(15, 70));
      i++;
    }
  } else if (waveBtn.clicked && towers.length === 0) {
    k = 80;
    insfundtexthue = 0;
  }
  if (mapNum === 1) spawnMobs(525);
  if (mapNum === 2) spawnMobs(250);
}

function drawBuildButton() {
  buildBtn.show();
  fill(white);
  textSize(150 / 4);
  drawText('BUILD', 900, 330);
  if (buildBtn.clicked && mobs.length === 0) {
    mode = BUILD;
    k = 0;
  }
}

function buildATowerText() {
  if (k > 0) {
    textSize(50);
    fillA(foxredl, insfundtexthue);
    drawText('BUILD A TOWER!', 400, 400);
    k--;
  }
  if (k > 60 && k !== 80) {
    insfundtexthue = insfundtexthue + 25;
  }
  if (k < 20 && k > 0) {
    insfundtexthue = insfundtexthue - 25;
  }
}

function drawLives() {
  fill(white);
  textSize(40);
  drawText('LIVES: ' + lives, 400, 50);

  if (lives === 0) {
    mode = GAMEOVER;
  }
}

function speedButtons() {
  speed1xButton.show();
  fill(white);
  textSize(60);
  drawText('1X', 900, 500);
  textSize(18);
  drawText('SPEED', 900, 540);

  if (speed1xButton.clicked) {
    multiplier = 1;
  }
  speed2xButton.show();
  fill(white);
  textSize(60);
  drawText('2X', 900, 675);
  textSize(18);
  drawText('SPEED', 900, 715);

  if (speed2xButton.clicked) {
    multiplier = 2;
  }
}

// ===================== BUILD ===========================
function build() {
  drawMaps();
  animateThings();
  drawBuildInterface();
  transactions();
  insufficientFunds();
}

function drawBuildInterface() {
  sidebar();
  drawPlayButton();
  buildModeText();
  buyGunButton();
  buyAoeButton();
  buyLaserButton();
}

function drawPlayButton() {
  playBtn.show();
  fill(white);
  textSize(150 / 4);
  drawText('PLAY', 900, 100);
  if (playBtn.clicked) {
    mode = PLAY;
    k = 0;
  }
}

function buyGunButton() {
  buyGunTowerButton.show();
  textSize(150 / 4);
  fill(white);
  drawText('GUN', 900, 325);
  textSize(18);
  drawText('$100', 900, 355);

  if (buyGunTowerButton.clicked && cashmoney >= 100 && !deduct100) {
    deduct100 = true;
    draw100 = cashmoney - 100;
    towers.push(new Tower(0, 0, 0, 65, GUN));
  } else if (buyGunTowerButton.clicked && cashmoney < 100) {
    k = 80;
    insfundtexthue = 0;
  }
}

function buyAoeButton() {
  buyAoeTowerButton.show();
  textSize(150 / 4);
  fill(white);
  drawText('aoe', 900, 500);
  textSize(18);
  drawText('$200', 900, 530);

  if (buyAoeTowerButton.clicked && cashmoney >= 200 && !deduct200) {
    deduct200 = true;
    draw200 = cashmoney - 200;
    towers.push(new Tower(0, 0, 0, 75, AOE));
  } else if (buyAoeTowerButton.clicked && cashmoney < 200) {
    k = 80;
    insfundtexthue = 0;
  }
}

function buyLaserButton() {
  buyLaserTowerButton.show();
  textSize(150 / 4.5);
  fill(white);
  drawText('laser', 900, 675);
  textSize(18);
  drawText('$300', 900, 703);

  if (buyLaserTowerButton.clicked && cashmoney >= 300 && !deduct300) {
    deduct300 = true;
    draw300 = cashmoney - 300;
    towers.push(new Tower(0, 0, 0, 180, LASER));
  } else if (buyLaserTowerButton.clicked && cashmoney < 300) {
    k = 80;
    insfundtexthue = 0;
  }
}

function buildModeText() {
  buildmodetexthue = sin(angle2) * 250;
  angle2 = angle2 + 0.075;
  fill(255, 255, 255, buildmodetexthue);
  textSize(75);
  drawText('BUILD MODE', 400, 80);
}

function transactions() {
  if (deduct100) {
    if (cashmoney > draw100) {
      cashmoney = cashmoney - 1;
    } else deduct100 = false;
  } else deduct100 = false;

  if (deduct200) {
    if (cashmoney > draw200) {
      cashmoney = cashmoney - 2;
    } else deduct200 = false;
  } else deduct200 = false;

  if (deduct300) {
    if (cashmoney > draw300) {
      cashmoney = cashmoney - 3;
    } else deduct300 = false;
  } else deduct300 = false;
}

function insufficientFunds() {
  if (k > 0) {
    textSize(40);
    fillA(foxredl, insfundtexthue);
    drawText('Insufficient', 400, 700);
    drawText('Funds', 400, 750);
    k--;
  }
  if (k > 60 && k !== 80) {
    insfundtexthue = insfundtexthue + 25;
  }
  if (k < 20 && k > 0) {
    insfundtexthue = insfundtexthue - 25;
  }
}

// ===================== CLASSES ===========================

// Button.pde - a clickable button
class Button {
  constructor(t, x, y, w, h, norm, high) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.highlight = high;
    this.normal = norm;
    this.clicked = false;
    this.label = '';
    this.img = null;
    if (typeof t === 'string') this.label = t;
    else this.img = t;
  }

  hovered() {
    return mouseX > this.x - this.w / 2 && mouseX < this.x + this.w / 2 &&
           mouseY > this.y - this.h / 2 && mouseY < this.y + this.h / 2;
  }

  show() {
    this.drawBody();
    this.drawLabel();
    this.checkForClick();
  }

  drawBody() {
    if (this.hovered()) fill(this.highlight);
    else fill(this.normal);
    stroke(this.normal);
    strokeWeight(10);
    rect(this.x, this.y, this.w, this.h, 30);
  }

  drawLabel() {
    textAlign(CENTER, CENTER);
    if (this.hovered()) fill(this.normal);
    else fill(this.highlight);
    if (this.img === null) {
      textSize(floor(this.w / 4));
      drawText(this.label, this.x, this.y);
    } else {
      image(this.img, this.x, this.y, this.w - 10, this.h - 10);
    }
  }

  checkForClick() {
    this.clicked = mouseWasReleased && this.hovered();
  }
}

// Gif.pde - plays an animation from a numbered set of frames
class Gif {
  constructor(p, n, s, x, y, w, h) {
    this.numFrames = n;
    this.speed = s;
    this.currentFrame = 0;
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.frames = [];
    for (let i = 0; i < n; i++) {
      this.frames[i] = loadImage(ASSETS[p][i]);
    }
  }

  show() {
    if (this.currentFrame === this.numFrames) this.currentFrame = 0; // loop
    image(this.frames[this.currentFrame], this.x, this.y, this.w, this.h);
    if (frameCount % this.speed === 0) this.currentFrame++;
  }
}

// Node.pde - invisible direction markers that steer mobs
// (called PathNode here because "Node" is a built-in browser class)
class PathNode {
  constructor(x, y, dx, dy, angle, m) {
    this.x = x;
    this.y = y;
    this.dx = dx;
    this.dy = dy;
    this.angle = angle;
    this.m = m;
  }

  show() {
    fill(black);
    stroke(black);
    circle(this.x, this.y, 10);
    strokeWeight(5);
    line(this.x, this.y, this.x + this.dx * 50, this.y + this.dy * 50);
  }
}

// Mob.pde - the monsters
class Mob {
  constructor(x, y, vx, vy, mobType) {
    this.x = x;
    this.y = y;
    this.vx = vx;
    this.vy = vy;
    this.mobType = mobType;
    this.d = 40;
    this.hp = 0;
    this.mhp = 0;
    this.vhp = 0;
    this.speed = 1;
    this.rotation = 0;
    this.healthbar = '#21CE22';
    this.healthbarStroke = '#1aa51b';

    if (mobType === 0) {
      this.hp = 3;
      this.mhp = this.hp;
      this.speed = 1;
    }
    if (mobType === 1) {
      this.hp = 2;
      this.mhp = this.hp;
      this.speed = 2;
    }
    if (mobType === 2) {
      this.hp = 8;
      this.mhp = this.hp;
      this.speed = 0.75;
    }
  }

  show() {
    this.vhp = this.hp * 10;
    strokeWeight(5);
    translate(this.x, this.y);
    if (this.rotation !== 0) {
      rotate(radians(this.rotation));
    }
    if (this.mobType === 0) {
      fill(foxredl);
      stroke(foxredd);
      circle(0, 0, this.d);
      strokeWeight(0);
      fill(black);
      circle(0 + 15, 0 - 7, this.d - 30);
      circle(0 + 15, 0 + 7, this.d - 30);
    }
    if (this.mobType === 1) {
      fill('#0096FF');
      stroke('#0047AB');
      circle(0, 0, this.d);
      strokeWeight(0);
      fill(black);
      circle(0 + 15, 0 - 7, this.d - 30);
      circle(0 + 15, 0 + 7, this.d - 30);
    }
    if (this.mobType === 2) {
      this.d = 50;
      fill('#ffff66');
      stroke('#cccc52');
      circle(0, 0, this.d);
      strokeWeight(0);
      fill(black);
      circle(0 + 15, 0 - 7, this.d - 40);
      circle(0 + 15, 0 + 7, this.d - 40);
    }
    endTransform();

    strokeWeight(2);
    stroke(this.healthbarStroke);
    fill(this.healthbar);
    rect(this.x, this.y + this.d - 15, this.vhp, 5, 3);
  }

  act() {
    this.x = this.x + this.vx * this.speed * multiplier;
    this.y = this.y + this.vy * this.speed * multiplier;
    if (this.x > 815) {
      this.hp = 0;
      lives = lives - 1;
    }

    if (this.hp <= this.mhp / 3 * 2) {
      this.healthbar = '#FFA500';
      this.healthbarStroke = '#e69500';
    }
    if (this.hp <= this.mhp / 3) {
      this.healthbar = '#FF3639';
      this.healthbarStroke = '#e63133';
    }

    for (let i = 0; i < nodes.length; i++) {
      if (nodes[i].m === mapNum && dist(nodes[i].x, nodes[i].y, this.x, this.y) < 4) {
        this.vx = nodes[i].dx;
        this.vy = nodes[i].dy;
        this.rotation = nodes[i].angle;
      }
    }

    let i = 0;
    while (i < bullets.length) {
      const myBullet = bullets[i];
      if (myBullet.bulletType === 0) {
        if (dist(myBullet.x, myBullet.y, this.x, this.y) < this.d / 2 + myBullet.d / 2) {
          this.hp = this.hp - 1;
          this.vhp = this.vhp - 10;
          myBullet.hp = myBullet.hp - 1;
        }
      }
      if (myBullet.bulletType === 1) {
        if (dist(myBullet.x, myBullet.y, this.x, this.y) < this.d / 2 + myBullet.p / 2) {
          if (multiplier === 1) {
            this.hp = this.hp - 0.04;
            this.vhp = this.vhp - 0.4;
          }
          if (multiplier === 2) {
            this.hp = this.hp - 0.05;
            this.vhp = this.vhp - 0.5;
          }
        }
      }
      if (myBullet.bulletType === 2) {
        const myMob = mobs[0];
        myMob.hp = myMob.hp - 0.008;
      }
      i++;
    }
  }
}

// Bullet.pde - gun bullets, AoE rings and lasers
class Bullet {
  constructor(x, y, vx, vy, bt) {
    this.x = x;
    this.y = y;
    this.vx = vx;
    this.vy = vy;
    this.d = 18;
    this.hp = 1;
    this.p = 55;
    this.bulletType = bt;
    this.towerangle = 0;
    this.aoehue = 0;

    if (bt === 1) this.aoehue = 255;
    if (bt === 2) this.aoehue = 0;
  }

  show() {
    if (this.bulletType === 0) {
      stroke(foxredd);
      strokeWeight(2);
      fill(foxredl);
      circle(this.x, this.y, this.d);
    }
    if (this.bulletType === 1) {
      if (this.aoehue > 0) {
        this.aoehue = this.aoehue - 19 * multiplier;
      }
      strokeWeight(0);
      stroke(rockgreyd);
      fill(255, 255, 255, this.aoehue);
      circle(this.x, this.y, this.p);
      strokeWeight(4);
      translate(this.x, this.y);
      rotate(radians(this.towerangle));
      fill(foxredd);
      triangle(25, 25, 12, 22, 22, 12);
      triangle(25, -25, 12, -22, 22, -12);
      triangle(-25, -25, -12, -22, -22, -12);
      triangle(-25, 25, -12, 22, -22, 12);
      fill(rockgreyl);
      circle(0, 0, 50);
      endTransform();
    }
    if (this.bulletType === 2) {
      if (this.aoehue < 1000) {
        this.aoehue = this.aoehue + 1.5 * multiplier;
      }
      if (mobs.length > 0) {
        strokeWeight(6);
        const myMob = mobs[0];
        strokeA(foxredd, this.aoehue);
        line(this.x, this.y, myMob.x, myMob.y);
      }
    }
    if (multiplier === 1 || multiplier === 2) {
      this.towerangle = this.towerangle + 14.5 * multiplier;
    }
  }

  act() {
    if (this.bulletType === 0) { // Gun bullets
      this.x = this.x + this.vx;
      this.y = this.y + this.vy;
    }

    if (this.bulletType === 1) { // AoE bullets
      this.p = this.p + 15 * multiplier;
    }

    if (this.bulletType === 2) { // Laser bullets
      this.p = this.p - 1;
      if (mobs.length > 0) {
        const myMob = mobs[0];
        if (myMob.hp < 0.1) {
          this.hp = 0;
          myMob.hp = myMob.hp - 0.2;
        }
      }

      if (mobs.length === 0) {
        this.hp = 0;
      }
    }
    if (this.x > 1050 || this.x < -50 || this.y > 850 || this.y < -50) {
      this.hp = this.hp - 1;
    }
    if (this.p > 240) {
      this.hp = this.hp - 1;
    }
    if (this.p < -180) {
      this.hp = this.hp - 1;
    }
  }
}

// Tower.pde - the player's defenses
class Tower {
  constructor(x, y, c, th, tt) {
    this.x = x;
    this.y = y;
    this.cooldown = c;
    this.threshold = th;
    this.towerMode = PLACING;
    this.towerType = tt;
  }

  // While placing, the tower follows the mouse drawn 1.25x bigger
  beginPlacingTransform() {
    translate(-mouseX / 4, -mouseY / 4);
    scale(1.25);
  }

  tryPlace() {
    if (mouseHeld) {
      this.towerMode = PLACED;
      this.x = mouseX;
      this.y = mouseY;
    }
  }

  show() {
    if (this.towerType === GUN) {
      stroke(rockgreyd);
      strokeWeight(4);
      if (this.towerMode === PLACED) {
        fill(foxredd);
        rect(this.x, this.y, 59, 20);
        rect(this.x, this.y, 20, 59);
        fill(rockgreyl);
        rect(this.x, this.y, 45, 45, 7);
      } else if (this.towerMode === PLACING) {
        this.beginPlacingTransform();
        fill(foxredd);
        rect(mouseX, mouseY, 59, 20);
        rect(mouseX, mouseY, 20, 59);
        fill(rockgreyl);
        rect(mouseX, mouseY, 45, 45, 7);
        endTransform();
        this.tryPlace();
      }
    }
    if (this.towerType === AOE) {
      stroke(rockgreyd);
      strokeWeight(4);
      fill(0, 0, 255);
      if (this.towerMode === PLACED) {
        if (this.cooldown < 80 && this.cooldown > 13) {
          this.drawAoe();
        }
        if (mode === BUILD || mobs.length === 0) {
          this.drawAoe();
        }
      } else if (this.towerMode === PLACING) {
        this.beginPlacingTransform();
        fill(foxredd);
        triangle(mouseX + 25, mouseY + 25, mouseX + 12, mouseY + 22, mouseX + 22, mouseY + 12);
        triangle(mouseX + 25, mouseY - 25, mouseX + 12, mouseY - 22, mouseX + 22, mouseY - 12);
        triangle(mouseX - 25, mouseY - 25, mouseX - 12, mouseY - 22, mouseX - 22, mouseY - 12);
        triangle(mouseX - 25, mouseY + 25, mouseX - 12, mouseY + 22, mouseX - 22, mouseY + 12);
        fill(rockgreyl);
        circle(mouseX, mouseY, 50);
        endTransform();
        this.tryPlace();
      }
    }
    if (this.towerType === LASER) {
      stroke(rockgreyd);
      strokeWeight(4);
      fill(foxredd);
      if (this.towerMode === PLACED) {
        fill(rockgreyl);
        circle(this.x, this.y, 50);
        circle(this.x, this.y, 15);
        fill(foxredd);
        circle(this.x, this.y, 12);
      } else if (this.towerMode === PLACING) {
        this.beginPlacingTransform();
        fill(rockgreyl);
        circle(mouseX, mouseY, 50);
        circle(mouseX, mouseY, 15);
        fill(foxredd);
        circle(mouseX, mouseY, 12);
        endTransform();
        this.tryPlace();
      }
    }
  }

  act() {
    this.cooldown = this.cooldown + 1 * multiplier;
    if (this.towerType === GUN) {
      if (this.cooldown >= this.threshold) {
        this.cooldown = 0;
        if (mobs.length > 0) {
          bullets.push(new Bullet(this.x, this.y, 0, -10, 0)); // UP
          bullets.push(new Bullet(this.x, this.y, 0, 10, 0));  // DOWN
          bullets.push(new Bullet(this.x, this.y, -10, 0, 0)); // LEFT
          bullets.push(new Bullet(this.x, this.y, 10, 0, 0));  // RIGHT
        }
      }
    }
    if (this.towerType === AOE) {
      if (this.cooldown >= this.threshold) {
        this.cooldown = 0;
        if (mobs.length > 0) {
          bullets.push(new Bullet(this.x, this.y, 10, 0, 1));
        }
      }
    }
    if (this.towerType === LASER) {
      if (this.cooldown >= this.threshold) {
        this.cooldown = 0;
        if (mobs.length > 0) {
          bullets.push(new Bullet(this.x, this.y, 10, 0, 2));
        }
      }
    }
  }

  drawAoe() {
    const x = this.x, y = this.y;
    fill(foxredd);
    triangle(x + 25, y + 25, x + 12, y + 22, x + 22, y + 12);
    triangle(x + 25, y - 25, x + 12, y - 22, x + 22, y - 12);
    triangle(x - 25, y - 25, x - 12, y - 22, x - 22, y - 12);
    triangle(x - 25, y + 25, x - 12, y + 22, x - 22, y + 12);
    fill(rockgreyl);
    circle(x, y, 50);
  }
}


